import React, { useState } from 'react';
import { useStripe, useElements, CardElement } from '@stripe/react-stripe-js';
import API from '../api/axiosClient';

export default function CheckoutForm({ orgId, amount, onSuccess, onCancel }) {
    const stripe = useStripe();
    const elements = useElements();
    const [loading, setLoading] = useState(false);
    const [errorMessage, setErrorMessage] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!stripe || !elements) return;

        setLoading(true);
        setErrorMessage('');

        try {
            // 1. Request clientSecret from your backend createTopUpIntent endpoint
            const res = await API.post(`/payment/${orgId}/create-intent`, { amount });
            const { clientSecret } = res.data;

            // 2. Confirm card payment with Stripe
            const cardElement = elements.getElement(CardElement);
            const payload = await stripe.confirmCardPayment(clientSecret, {
                payment_method: {
                    card: cardElement,
                }
            });

            if (payload.error) {
                setErrorMessage(payload.error.message);
                setLoading(false);
            } else if (payload.paymentIntent.status === 'succeeded') {
                setLoading(false);
                onSuccess(amount);
            }
        } catch (err) {
            setErrorMessage(err.response?.data?.error || 'Payment processing failed');
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-4 bg-gray-900 p-6 rounded-xl border border-gray-700">
            <h4 className="font-semibold text-white text-lg">Enter Card Details for ${amount} Top-Up</h4>
            
            <div className="p-3 bg-gray-800 border border-gray-700 rounded-lg">
                <CardElement options={{
                    style: {
                        base: {
                            color: '#ffffff',
                            fontFamily: 'monospace',
                            fontSize: '16px',
                            '::placeholder': { color: '#9ca3af' },
                        },
                        invalid: { color: '#ef4444' }
                    }
                }} />
            </div>

            {errorMessage && <p className="text-red-400 text-sm">{errorMessage}</p>}

            <div className="flex gap-3">
                <button 
                    type="submit" 
                    disabled={!stripe || loading}
                    className="flex-1 bg-emerald-600 hover:bg-emerald-500 disabled:bg-gray-700 p-3 rounded-lg font-semibold text-white transition"
                >
                    {loading ? 'Processing...' : `Pay $${amount}`}
                </button>
                <button 
                    type="button" 
                    onClick={onCancel}
                    className="bg-gray-700 hover:bg-gray-600 px-4 py-3 rounded-lg font-semibold text-white transition"
                >
                    Cancel
                </button>
            </div>
        </form>
    );
}
